css:
:where(.wtyg-map-site_enslaved_microbes){--bg:#0b0e13;--panel:#10151d;--panel2:#171e28;--line:#262f3b;--ink:#e6ebf1;--ink-dim:#8d99a8;--accent:#7fa8d0}
:where(.wtyg-map-site_enslaved_microbes) *{box-sizing:border-box}
:where(.wtyg-map-site_enslaved_microbes),:where(.wtyg-map-site_enslaved_microbes){height:100%;margin:0}
:where(.wtyg-map-site_enslaved_microbes){font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;background:var(--bg);color:var(--ink);-webkit-font-smoothing:antialiased}
:where(.wtyg-map-site_enslaved_microbes) :is([data-wtyg-id="map"],#wtyg-noid-map){position:absolute;inset:0;background:#0b0e13}
:where(.wtyg-map-site_enslaved_microbes) .tabs{position:absolute;top:14px;left:50%;transform:translateX(-50%);z-index:700;display:flex;gap:2px;background:rgba(9,12,17,.9);border:1px solid var(--line);border-radius:8px;padding:3px;box-shadow:0 2px 14px rgba(0,0,0,.4)}
:where(.wtyg-map-site_enslaved_microbes) .tab{background:transparent;border:0;color:var(--ink-dim);font:inherit;font-size:12px;font-weight:600;letter-spacing:.03em;padding:7px 14px;border-radius:6px;cursor:pointer;transition:color .15s,background .15s;white-space:nowrap}
:where(.wtyg-map-site_enslaved_microbes) .tab:hover{color:var(--ink)}
:where(.wtyg-map-site_enslaved_microbes) .tab.on{background:var(--panel2);color:var(--ink);box-shadow:inset 0 0 0 1px var(--line)}
:where(.wtyg-map-site_enslaved_microbes) .title{position:absolute;top:60px;left:14px;z-index:600;background:rgba(9,12,17,.78);backdrop-filter:blur(8px);border:1px solid var(--line);border-radius:10px;padding:12px 15px;max-width:398px;box-shadow:0 2px 18px rgba(0,0,0,.35)}
:where(.wtyg-map-site_enslaved_microbes) .title h1{margin:0;font-size:13.5px;letter-spacing:.08em;text-transform:uppercase;font-weight:700;line-height:1.3}
:where(.wtyg-map-site_enslaved_microbes) .title p{margin:6px 0 0;font-size:11px;color:var(--ink-dim);line-height:1.5}
:where(.wtyg-map-site_enslaved_microbes) .title .mono{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;letter-spacing:0}
:where(.wtyg-map-site_enslaved_microbes) .panel{position:absolute;top:14px;right:14px;z-index:600;width:316px;max-width:calc(100vw - 28px);background:rgba(16,21,29,.93);backdrop-filter:blur(8px);border:1px solid var(--line);border-radius:10px;display:flex;flex-direction:column;max-height:calc(100vh - 28px);box-shadow:0 2px 18px rgba(0,0,0,.4)}
:where(.wtyg-map-site_enslaved_microbes) .panel .pad{padding:13px 13px 11px}
:where(.wtyg-map-site_enslaved_microbes) .search{width:100%;background:var(--panel2);border:1px solid var(--line);border-radius:7px;color:var(--ink);padding:9px 11px;font-size:13px;outline:none;transition:border-color .15s}
:where(.wtyg-map-site_enslaved_microbes) .search::placeholder{color:#5e6b7a}
:where(.wtyg-map-site_enslaved_microbes) .search:focus{border-color:#3f5a76}
:where(.wtyg-map-site_enslaved_microbes) .legend{margin-top:11px;display:flex;flex-direction:column;gap:3px}
:where(.wtyg-map-site_enslaved_microbes) .leg{display:flex;align-items:center;gap:9px;cursor:pointer;user-select:none;font-size:12px;padding:5px 6px;border-radius:6px;transition:background .12s}
:where(.wtyg-map-site_enslaved_microbes) .leg:hover{background:var(--panel2)}
:where(.wtyg-map-site_enslaved_microbes) .leg.off{opacity:.38}
:where(.wtyg-map-site_enslaved_microbes) .leg .dot{width:10px;height:10px;border-radius:2px;flex:0 0 auto;box-shadow:0 0 0 1px rgba(255,255,255,.18)}
:where(.wtyg-map-site_enslaved_microbes) .leg .lab{flex:1;color:var(--ink)}
:where(.wtyg-map-site_enslaved_microbes) .leg .cnt{font-family:ui-monospace,monospace;color:var(--ink-dim);font-size:11px}
:where(.wtyg-map-site_enslaved_microbes) .sizenote{font-size:10.5px;color:#5f6b79;margin-top:10px;line-height:1.5}
:where(.wtyg-map-site_enslaved_microbes) .meta{display:flex;justify-content:space-between;align-items:center;font-size:11px;color:var(--ink-dim);margin-top:10px;padding-top:9px;border-top:1px solid var(--line)}
:where(.wtyg-map-site_enslaved_microbes) .meta a{color:var(--accent);text-decoration:none;cursor:pointer}
:where(.wtyg-map-site_enslaved_microbes) .meta a:hover{color:#a9c8e6}
:where(.wtyg-map-site_enslaved_microbes) .listwrap{overflow:auto;border-top:1px solid var(--line);padding:6px 6px 9px}
:where(.wtyg-map-site_enslaved_microbes) .listwrap::-webkit-scrollbar{width:8px}
:where(.wtyg-map-site_enslaved_microbes) .listwrap::-webkit-scrollbar-thumb{background:#2a3543;border-radius:8px}
:where(.wtyg-map-site_enslaved_microbes) .row{display:flex;gap:9px;align-items:flex-start;padding:7px 8px;border-radius:7px;cursor:pointer;transition:background .12s}
:where(.wtyg-map-site_enslaved_microbes) .row:hover{background:var(--panel2)}
:where(.wtyg-map-site_enslaved_microbes) .row .rk{font-family:ui-monospace,monospace;font-size:11px;color:var(--ink-dim);min-width:22px;text-align:right;margin-top:1px}
:where(.wtyg-map-site_enslaved_microbes) .row .bar{width:3px;align-self:stretch;border-radius:2px;flex:0 0 auto;margin-top:1px}
:where(.wtyg-map-site_enslaved_microbes) .row .nm{font-size:12.5px;line-height:1.3;font-weight:600}
:where(.wtyg-map-site_enslaved_microbes) .row .sub{font-size:10.5px;color:var(--ink-dim);margin-top:2px;line-height:1.35}
:where(.wtyg-map-site_enslaved_microbes) .row .sub .mono{font-family:ui-monospace,monospace}
:where(.wtyg-map-site_enslaved_microbes) .leaflet-pane path.mk{filter:drop-shadow(0 1px 2px rgba(0,0,0,.55))}
:where(.wtyg-map-site_enslaved_microbes) .leaflet-popup-content-wrapper{background:var(--panel);color:var(--ink);border-radius:10px;border:1px solid var(--line);box-shadow:0 6px 26px rgba(0,0,0,.5)}
:where(.wtyg-map-site_enslaved_microbes) .leaflet-popup-tip{background:var(--panel);border:1px solid var(--line)}
:where(.wtyg-map-site_enslaved_microbes) .leaflet-popup-content{margin:12px 14px;font-size:12.5px;line-height:1.5;min-width:238px}
:where(.wtyg-map-site_enslaved_microbes) .pop h3{margin:0 0 2px;font-size:14px;line-height:1.3;font-weight:700}
:where(.wtyg-map-site_enslaved_microbes) .pop .rkbig{font-family:ui-monospace,monospace;font-size:10.5px;color:var(--ink-dim);letter-spacing:.04em;text-transform:uppercase}
:where(.wtyg-map-site_enslaved_microbes) .pop .tag{display:inline-block;font-size:9.5px;letter-spacing:.06em;text-transform:uppercase;padding:3px 8px;border-radius:4px;margin:7px 0 8px;font-weight:700;color:#0b0e13}
:where(.wtyg-map-site_enslaved_microbes) .pop .kv{margin:3px 0}
:where(.wtyg-map-site_enslaved_microbes) .pop .kv b{color:var(--ink-dim);font-weight:600}
:where(.wtyg-map-site_enslaved_microbes) .pop .note{margin-top:8px;padding-top:7px;border-top:1px solid var(--line);color:#c4cedb;font-size:11.5px}
:where(.wtyg-map-site_enslaved_microbes) .leaflet-bar a{background:#171e28;color:#e6ebf1;border-bottom:1px solid var(--line)}
:where(.wtyg-map-site_enslaved_microbes) .leaflet-bar a:hover{background:#222c39}
:where(.wtyg-map-site_enslaved_microbes) .leaflet-control-attribution{background:rgba(9,12,17,.72)!important;color:#6c7785!important;font-size:10px!important}
:where(.wtyg-map-site_enslaved_microbes) .leaflet-control-attribution a{color:#8fa9c2!important}
:where(.wtyg-map-site_enslaved_microbes) .leaflet-control-layers{background:rgba(16,21,29,.96)!important;color:var(--ink)!important;border:1px solid var(--line)!important;border-radius:8px!important}
:where(.wtyg-map-site_enslaved_microbes) .leaflet-control-layers-expanded{padding:9px 11px!important}
@media (max-width:640px){:where(.wtyg-map-site_enslaved_microbes) .title{max-width:calc(100vw - 28px);left:8px;padding:9px 11px}
:where(.wtyg-map-site_enslaved_microbes) .title h1{font-size:12px}
:where(.wtyg-map-site_enslaved_microbes) .panel{width:calc(100vw - 28px);top:auto;bottom:14px;right:14px;max-height:44vh}
:where(.wtyg-map-site_enslaved_microbes) .tabs{top:8px;font-size:11px}
:where(.wtyg-map-site_enslaved_microbes) .tab{padding:7px 9px}}
